from __future__ import annotations


def render_challenge_ui(*, llm_connected: bool) -> str:
    """Return the judge-facing full challenge-data shell."""

    interpreter = (
        "OpenAI GPT-6 Luna · deterministic policy authority retained"
        if llm_connected
        else "Deterministic interpreter · deterministic policy authority retained"
    )
    mode_badge = "LIVE LLM · FULL DATA" if llm_connected else "FULL DATA · LOCAL"
    html = r'''<!doctype html>
<html lang="en">
<head>
<meta charset="utf-8">
<meta name="viewport" content="width=device-width,initial-scale=1">
<title>Proof of One — Deterministic Support Interlock</title>
<style>
:root{color-scheme:dark;--bg:#0c130d;--panel:#152018;--panel2:#203026;--cream:#f6edcf;--cream2:#e7ddbd;--muted:#adb7a7;--line:rgba(246,237,207,.22);--green:#34d477;--red:#ff665c;--amber:#ffd15c;--blue:#6aa0ff;--purple:#bb8cff;--off:#263126;--shadow:0 26px 70px rgba(0,0,0,.36);font-family:"IBM Plex Mono","Cascadia Mono",Consolas,monospace}*{box-sizing:border-box}body{margin:0;min-height:100vh;color:var(--cream);background:radial-gradient(circle at 12% 0%,rgba(66,105,71,.38),transparent 30rem),radial-gradient(circle at 88% 4%,rgba(116,83,41,.30),transparent 25rem),linear-gradient(145deg,#08100a 0%,#111a13 54%,#172017 100%)}.page{width:min(1500px,calc(100vw - 32px));margin:0 auto;padding:24px 0 34px}.shell{overflow:hidden;border:1px solid rgba(246,237,207,.28);border-radius:28px;background:rgba(17,25,18,.95);box-shadow:var(--shadow)}.topbar{display:grid;grid-template-columns:minmax(0,1fr) auto;gap:20px;align-items:center;padding:24px 28px;border-bottom:1px solid var(--line);background:linear-gradient(180deg,rgba(14,27,16,.98),rgba(18,28,20,.92))}.brand h1{margin:0;color:var(--cream);font-size:clamp(28px,4.2vw,56px);line-height:1;letter-spacing:.08em;text-transform:uppercase;text-shadow:0 0 20px rgba(246,237,207,.18);white-space:nowrap}.brand p{margin:10px 0 0;max-width:960px;color:var(--muted);font-family:Inter,system-ui,sans-serif;font-size:15px;line-height:1.45}.badge-row{display:flex;gap:12px;flex-wrap:wrap;justify-content:flex-end}.badge{border:1px solid rgba(246,237,207,.34);border-radius:999px;padding:12px 17px;color:var(--cream);background:rgba(255,255,255,.07);font-weight:900;letter-spacing:.09em;text-transform:uppercase;white-space:nowrap}.main{display:grid;grid-template-columns:minmax(320px,390px) minmax(0,1fr);gap:18px;padding:20px}.card{border:1px solid var(--line);border-radius:24px;background:linear-gradient(180deg,rgba(32,48,38,.97),rgba(18,28,20,.98));box-shadow:0 14px 36px rgba(0,0,0,.23)}.controls{display:grid;gap:14px;align-content:start;padding:20px}.section-title{margin:0;color:var(--cream);font-size:19px;letter-spacing:.12em;text-transform:uppercase}.field label{display:block;margin-bottom:8px;color:var(--muted);font-size:12px;font-weight:900;letter-spacing:.12em;text-transform:uppercase}input,select,textarea,button{width:100%;border-radius:14px;font:inherit}input,select,textarea{border:1px solid rgba(246,237,207,.25);background:rgba(8,14,9,.72);color:var(--cream);padding:12px 13px}textarea{min-height:118px;line-height:1.45;resize:vertical}button{border:1px solid rgba(246,237,207,.28);background:#111810;color:var(--cream);cursor:pointer;font-weight:900;letter-spacing:.035em;padding:12px 14px;text-transform:uppercase}button:hover:not(:disabled),button:focus-visible{outline:2px solid rgba(246,237,207,.36);outline-offset:2px;background:#1d281f}button:disabled{opacity:.45;cursor:not-allowed}.primary{background:#243623;border-color:rgba(52,212,119,.48)}.human{background:rgba(82,49,108,.72);border-color:rgba(187,140,255,.55)}.revoke{background:rgba(92,38,34,.72);border-color:rgba(255,102,92,.55)}.two{display:grid;grid-template-columns:1fr 1fr;gap:10px}.session-box,.error{border-radius:16px;padding:12px;font-family:Inter,system-ui,sans-serif;font-size:13px;line-height:1.45}.session-box{color:var(--muted);background:rgba(246,237,207,.07);border:1px solid rgba(246,237,207,.18);overflow-wrap:anywhere}.error{display:none;color:#ffd8d5;border:1px solid rgba(255,102,92,.45);background:rgba(255,102,92,.10)}.board{display:grid;grid-template-rows:auto auto auto;gap:18px}.route-board{display:grid;grid-template-columns:minmax(0,1fr) 130px;gap:18px;min-height:330px;padding:28px;border-radius:28px;background:#08110a;border:1px solid rgba(246,237,207,.22);box-shadow:inset 0 0 0 1px rgba(52,212,119,.05)}.route-word{overflow:hidden;align-self:start;color:var(--cream);font-size:clamp(54px,9vw,126px);font-weight:1000;letter-spacing:.09em;line-height:.88;text-transform:uppercase;text-overflow:clip}.lamp-wrap{display:grid;place-items:start center;padding-top:22px}.lamp{width:96px;height:96px;border-radius:50%;background:radial-gradient(circle at 50% 42%,#687466,#344033 56%,#182018 57%);border:14px solid #3a4539;box-shadow:0 0 0 10px rgba(52,212,119,.08),inset 0 0 18px rgba(0,0,0,.35)}.lamp.on.green{background:radial-gradient(circle at 50% 42%,#37dc80,#25b766 58%,#145e39 59%);border-color:#28533a;box-shadow:0 0 34px rgba(52,212,119,.74),0 0 0 12px rgba(52,212,119,.16)}.lamp.on.red{background:radial-gradient(circle at 50% 42%,#ff746b,#bf3d37 58%,#5e1f1b 59%);border-color:#55302e;box-shadow:0 0 34px rgba(255,102,92,.70),0 0 0 12px rgba(255,102,92,.16)}.lamp.on.amber{background:radial-gradient(circle at 50% 42%,#ffe08a,#d59b25 58%,#6e4f12 59%);border-color:#66532a;box-shadow:0 0 34px rgba(255,209,92,.70),0 0 0 12px rgba(255,209,92,.16)}.lamp.on.blue{background:radial-gradient(circle at 50% 42%,#8bb7ff,#4d83df 58%,#254476 59%);border-color:#34445f;box-shadow:0 0 34px rgba(106,160,255,.70),0 0 0 12px rgba(106,160,255,.16)}.lamp.on.purple{background:radial-gradient(circle at 50% 42%,#cba4ff,#8d65dd 58%,#493071 59%);border-color:#4c3b61;box-shadow:0 0 34px rgba(187,140,255,.70),0 0 0 12px rgba(187,140,255,.16)}.status-copy{grid-column:1 / -1;margin:6px 0 0;color:var(--muted);font-family:Inter,system-ui,sans-serif;font-size:22px;line-height:1.45}.response{grid-column:1 / -1;border:1px solid rgba(246,237,207,.24);border-radius:22px;background:rgba(246,237,207,.05);padding:26px;color:var(--cream);font-family:Inter,system-ui,sans-serif;font-size:26px;line-height:1.55;min-height:128px}.route-board.busy .lamp{animation:pulse 1s infinite}.route-board.busy .route-word{animation:scan 1.2s infinite}@keyframes pulse{0%,100%{filter:brightness(.85)}50%{filter:brightness(1.55)}}@keyframes scan{0%,100%{opacity:.72}50%{opacity:1}}.checks{display:grid;grid-template-columns:repeat(4,minmax(0,1fr));gap:16px}.check{min-height:210px;border:1px solid rgba(246,237,207,.20);border-radius:24px;background:rgba(246,237,207,.06);padding:24px 24px 20px;color:var(--cream2);position:relative}.check-head{display:grid;grid-template-columns:minmax(0,1fr) 72px;gap:12px;align-items:center}.check-title{font-size:22px;line-height:1.15;font-weight:1000;letter-spacing:.12em;text-transform:uppercase}.mini-lamp{justify-self:end;width:62px;height:62px;border-radius:50%;background:radial-gradient(circle at 50% 42%,#5b6559,#303a30 58%,#151c16 59%);border:9px solid #303a30}.check.active .mini-lamp{background:radial-gradient(circle at 50% 42%,#37dc80,#25b766 58%,#145e39 59%);box-shadow:0 0 25px rgba(52,212,119,.64)}.check.red.active .mini-lamp{background:radial-gradient(circle at 50% 42%,#ff746b,#bf3d37 58%,#5e1f1b 59%);box-shadow:0 0 25px rgba(255,102,92,.64)}.check.amber.active .mini-lamp{background:radial-gradient(circle at 50% 42%,#ffe08a,#d59b25 58%,#6e4f12 59%);box-shadow:0 0 25px rgba(255,209,92,.64)}.check.blue.active .mini-lamp{background:radial-gradient(circle at 50% 42%,#8bb7ff,#4d83df 58%,#254476 59%);box-shadow:0 0 25px rgba(106,160,255,.64)}.check p{margin:28px 0 0;color:var(--cream);font-family:Inter,system-ui,sans-serif;font-size:22px;line-height:1.45}.lower{display:grid;grid-template-columns:minmax(0,1fr) minmax(330px,420px);gap:16px}.why,.evidence{padding:22px}.why h2,.evidence h2{margin:0 0 18px;color:var(--cream);font-size:22px;letter-spacing:.13em;text-transform:uppercase}.why p{margin:0;color:var(--cream2);font-family:Inter,system-ui,sans-serif;font-size:20px;line-height:1.5}.evidence{text-align:center}.evidence-grid{display:grid;grid-template-columns:1fr 1fr;gap:14px}.e-card{border:1px solid rgba(246,237,207,.22);border-radius:18px;background:rgba(246,237,207,.07);padding:16px;min-height:96px}.e-card strong{display:block;text-align:center;color:var(--muted);font-size:16px;font-weight:1000;letter-spacing:.13em;text-transform:uppercase}.e-card span{display:block;margin-top:12px;color:var(--cream);font-family:Inter,system-ui,sans-serif;font-size:20px;overflow-wrap:anywhere}.foot{padding:0 20px 20px;color:var(--muted);font-family:Inter,system-ui,sans-serif;font-size:13px}.hidden{display:none!important}@media(max-width:1000px){.topbar,.main,.lower{grid-template-columns:1fr}.checks{grid-template-columns:1fr 1fr}.route-board{grid-template-columns:1fr}.lamp-wrap{place-items:center}.brand h1{white-space:normal}}@media(max-width:640px){.checks,.evidence-grid{grid-template-columns:1fr}.route-word{font-size:48px}.response{font-size:20px}}
</style>
</head>
<body>
<div class="page"><div class="shell">
  <header class="topbar">
    <div class="brand">
      <h1>Deterministic Support Interlock</h1>
      <p>Customer-scoped records · LLM interpretation · deterministic route authority · visible verification.</p>
    </div>
    <div class="badge-row"><div class="badge" id="languageBadge">ES/PT line</div><div class="badge" id="modeBadge">__MODE_BADGE__</div></div>
  </header>
  <main class="main">
    <section class="card controls">
      <h2 class="section-title">Challenge data</h2>
      <div class="field"><label for="customerQuery">Customer ID prefix</label><input id="customerQuery" placeholder="Leave blank, then Search"></div>
      <button id="searchBtn" class="primary">Search customers</button>
      <div class="field"><label for="customerSelect">Matching customer</label><select id="customerSelect"><option value="">Search first</option></select></div>
      <button id="sessionBtn" class="primary" disabled>Start scoped session</button>
      <div id="sessionBox" class="session-box">No scoped customer session yet.</div>
      <div class="field"><label for="messageSelect">Provided messages</label><select id="messageSelect" disabled><option value="">Start a session first</option></select></div>
      <button id="useMessageBtn" disabled>Use selected message</button>
      <div class="field"><label for="messageInput">Customer message</label><textarea id="messageInput" placeholder="Choose a provided message or type a custom Spanish/Portuguese request."></textarea></div>
      <button id="sendBtn" class="primary" disabled>Set route · send</button>
      <div class="two"><button id="handoffBtn" class="human" disabled>Human review</button><button id="revokeBtn" class="revoke" disabled>Revoke session</button></div>
      <div id="errorBox" class="error"></div>
    </section>
    <section class="board">
      <div id="routeBoard" class="route-board">
        <div id="routeWord" class="route-word">Waiting</div>
        <div class="lamp-wrap"><div id="mainLamp" class="lamp"></div></div>
        <p id="statusCopy" class="status-copy">Interpreter: __INTERPRETER__</p>
        <div id="responseBox" class="response">Start a scoped customer session, then send a provided or custom message.</div>
      </div>
      <div class="checks">
        <article id="checkInterpreter" class="check"><div class="check-head"><div class="check-title">1 · Interpreter</div><div class="mini-lamp"></div></div><p id="interpreterText">Awaiting message.</p></article>
        <article id="checkScope" class="check"><div class="check-head"><div class="check-title">2 · Customer scope</div><div class="mini-lamp"></div></div><p id="scopeText">No customer session yet.</p></article>
        <article id="checkRoute" class="check"><div class="check-head"><div class="check-title">3 · Route authority</div><div class="mini-lamp"></div></div><p id="routeText">No route selected.</p></article>
        <article id="checkVerify" class="check"><div class="check-head"><div class="check-title">4 · Act → verify</div><div class="mini-lamp"></div></div><p id="verifyText">No action invoked.</p></article>
      </div>
      <div class="lower">
        <section class="card why"><h2>Why this route</h2><p id="whyText">The interlock is waiting for a customer-scoped message.</p></section>
        <section class="card evidence"><h2>Decision evidence</h2><div class="evidence-grid">
          <div class="e-card"><strong>Route</strong><span id="evRoute">waiting</span></div><div class="e-card"><strong>Intent</strong><span id="evIntent">unknown</span></div>
          <div class="e-card"><strong>Language</strong><span id="evLanguage">—</span></div><div class="e-card"><strong>Reference</strong><span id="evReference">not required</span></div>
          <div class="e-card"><strong>Control</strong><span id="evControl">waiting</span></div><div class="e-card"><strong>Verify</strong><span id="evVerify">not invoked</span></div>
          <div class="e-card"><strong>Action</strong><span id="evAction">none</span></div><div class="e-card"><strong>Execution</strong><span id="evExecution">not invoked</span></div>
        </div></section>
      </div>
    </section>
  </main>
  <div class="foot">Full challenge data · read-only · customer scoped · deterministic route authority · not fraud detection · not production or pilot readiness.</div>
</div></div>
<script>
const $ = (id) => document.getElementById(id);
const state = {session:null, customer:null, messages:[]};
const routeColor = {ANSWER:'green',CLARIFY:'amber',ABSTAIN:'blue',ESCALATE:'red',HANDOFF:'purple',WAITING:''};
function showError(msg){$('errorBox').style.display = msg ? 'block' : 'none'; $('errorBox').textContent = msg || '';}
function esc(v){return String(v ?? '').replace(/[&<>"]/g, c => ({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;'}[c]));}
async function api(url, opts={}){const r=await fetch(url, opts); let data=null; try{data=await r.json();}catch(e){} if(!r.ok){throw new Error(data?.detail || `${r.status} ${r.statusText}`);} return data;}
function setBusy(on){$('sendBtn').disabled = on || !state.session; $('routeBoard').classList.toggle('busy', on); if(on){$('routeWord').textContent='Routing'; $('responseBox').textContent='Setting route through the interlock...';}}
function setChecks(route, ev={}){for(const id of ['checkInterpreter','checkScope','checkRoute','checkVerify']){$(id).className='check';} $('checkInterpreter').classList.add('active'); $('checkScope').classList.add('active'); $('checkRoute').classList.add('active'); $('checkVerify').classList.add('active'); const color=routeColor[route]||''; if(route==='ESCALATE'){$('checkRoute').classList.add('red');} if(route==='CLARIFY'){$('checkRoute').classList.add('amber');} if(route==='ABSTAIN'){$('checkRoute').classList.add('blue');} $('interpreterText').textContent=`Language ${ev.language || 'auto'} · intent ${ev.intent || 'unknown'} · status verified`; $('scopeText').textContent='Customer-scoped records checked.'; $('routeText').textContent=`Route authority: ${route.toLowerCase()}.`; $('verifyText').textContent=ev.verify || ev.execution || (route==='ANSWER'?'banking fact verified':'no banking action');}
function renderDecision(data){const ev=data.decision_evidence || data.evidence || {}; const route=String(ev.route || data.route || data.control_route || data.decision_route || 'WAITING').toUpperCase(); const color=routeColor[route]||''; $('routeWord').textContent=route; $('mainLamp').className=`lamp ${color ? 'on '+color : ''}`; $('languageBadge').textContent=(ev.language || data.language || 'ES/PT').toUpperCase()+' line'; const reply=data.customer_message || data.reply || data.answer || data.response_text || data.message || data.detail || 'Request processed.'; $('responseBox').textContent=reply; $('whyText').textContent=ev.reason || ev.why || data.reason || `The interlock selected ${route.toLowerCase()} from interpreted intent, customer scope, and route authority.`; $('evRoute').textContent=route.toLowerCase(); $('evIntent').textContent=ev.intent || data.intent || 'unknown'; $('evLanguage').textContent=ev.language || data.language || 'auto'; $('evReference').textContent=ev.reference || ev.transaction_id || data.transaction_id || 'not required'; $('evControl').textContent=ev.control || ev.control_reason || data.control_reason || 'deterministic policy'; $('evVerify').textContent=ev.verify || data.verification || 'checked'; $('evAction').textContent=ev.action || data.action || 'none'; $('evExecution').textContent=ev.execution || data.execution_status || 'not invoked'; setChecks(route, ev);}
async function searchCustomers(){showError(''); const q=$('customerQuery').value.trim(); const customers=await api(`/api/challenge/customers?query=${encodeURIComponent(q)}&limit=20`); $('customerSelect').innerHTML=''; for(const c of customers){const opt=document.createElement('option'); opt.value=c.customer_id; opt.textContent=`${c.customer_id} · ${c.country || 'country n/a'} · ${c.default_language || 'lang'} · ${c.transcript_count || 0} messages`; opt.dataset.customer=JSON.stringify(c); $('customerSelect').appendChild(opt);} $('sessionBtn').disabled=!customers.length; if(customers.length){state.customer=customers[0];}}
async function startSession(){showError(''); const opt=$('customerSelect').selectedOptions[0]; if(!opt) return; state.customer=JSON.parse(opt.dataset.customer); const session=await api('/api/challenge/sessions',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({customer_id:state.customer.customer_id})}); state.session=session; $('sessionBox').innerHTML=`Scoped session active<br>Customer: ${esc(session.customer_id)}<br>Profile language: ${esc(session.language)}<br>Transcripts: ${esc(session.transcript_count)}`; $('sendBtn').disabled=false; $('handoffBtn').disabled=false; $('revokeBtn').disabled=false; await loadMessages(session.customer_id);}
async function loadMessages(customerId){const messages=await api(`/api/challenge/customers/${encodeURIComponent(customerId)}/messages?limit=25&offset=0`); state.messages=messages; $('messageSelect').disabled=false; $('messageSelect').innerHTML=''; for(const m of messages){const opt=document.createElement('option'); opt.value=m.customer_text; opt.textContent=`${m.process_date || 'date n/a'} · ${m.detected_language || 'lang n/a'} · ${(m.customer_text || '').slice(0,80)}`; $('messageSelect').appendChild(opt);} $('useMessageBtn').disabled=!messages.length; if(messages.length){$('messageInput').value=messages[0].customer_text;}}
async function sendMessage(){if(!state.session) return; showError(''); setBusy(true); try{const data=await api('/api/customer/turn',{method:'POST',headers:{'Content-Type':'application/json','X-Demo-Session':state.session.session_id},body:JSON.stringify({message:$('messageInput').value})}); renderDecision(data);}catch(e){showError(e.message);}finally{setBusy(false);}}
async function handoff(){if(!state.session) return; showError(''); setBusy(true); try{const data=await api('/api/customer/handoff',{method:'POST',headers:{'X-Demo-Session':state.session.session_id}}); renderDecision({route:'HANDOFF',customer_message:'Registered this case for human review.',decision_evidence:{route:'HANDOFF',intent:'human_review',language:state.session.language,control:'human review requested',verify:'ticket persisted',execution:'verified',action:data.ticket_id || data.escalation_id || 'human review'}});}catch(e){showError(e.message);}finally{setBusy(false);}}
async function revoke(){if(!state.session) return; showError(''); await fetch('/api/demo/session',{method:'DELETE',headers:{'X-Demo-Session':state.session.session_id}}); state.session=null; $('sessionBox').textContent='Session revoked.'; $('sendBtn').disabled=true; $('handoffBtn').disabled=true; $('revokeBtn').disabled=true; $('messageSelect').disabled=true; $('useMessageBtn').disabled=true; $('routeWord').textContent='Waiting'; $('mainLamp').className='lamp'; $('responseBox').textContent='Start a scoped customer session, then send a provided or custom message.';}
$('searchBtn').addEventListener('click',()=>searchCustomers().catch(e=>showError(e.message))); $('customerSelect').addEventListener('change',()=>{const opt=$('customerSelect').selectedOptions[0]; if(opt){state.customer=JSON.parse(opt.dataset.customer);}}); $('sessionBtn').addEventListener('click',()=>startSession().catch(e=>showError(e.message))); $('useMessageBtn').addEventListener('click',()=>{$('messageInput').value=$('messageSelect').value || '';}); $('sendBtn').addEventListener('click',sendMessage); $('handoffBtn').addEventListener('click',handoff); $('revokeBtn').addEventListener('click',()=>revoke().catch(e=>showError(e.message))); searchCustomers().catch(()=>{});
</script>
</body>
</html>'''
    return html.replace("__MODE_BADGE__", mode_badge).replace("__INTERPRETER__", interpreter)
